CREATE FUNCTION public.k3_goal_save(_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE g public.k3_goals; old public.k3_goals; p jsonb:=_payload; _id uuid:=nullif(p->>'id','')::uuid; typ text:=p->>'period_type'; dt date:=nullif(p->>'period_start','')::date; key uuid:=nullif(p->>'request_key','')::uuid; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập.'; END IF; PERFORM pg_advisory_xact_lock(hashtext('k3owner'),hashtext(auth.uid()::text));
 IF _id IS NOT NULL THEN SELECT * INTO old FROM public.k3_goals WHERE id=_id FOR UPDATE; IF old.id IS NULL OR old.user_id<>auth.uid() THEN RAISE EXCEPTION 'Bạn không được sửa mục tiêu của người khác.'; END IF; IF (p->>'revision')::bigint IS DISTINCT FROM old.revision THEN RAISE EXCEPTION 'Mục tiêu đã thay đổi. Vui lòng tải lại.'; END IF; typ:=old.period_type;dt:=old.period_start; ELSE IF key IS NULL THEN RAISE EXCEPTION 'Thiếu mã yêu cầu lưu mục tiêu.'; END IF; SELECT * INTO g FROM public.k3_goals WHERE user_id=auth.uid() AND request_key=key; IF g.id IS NOT NULL THEN RETURN to_jsonb(g); END IF; END IF;
 dt:=public.k3_period_start(typ,dt); IF dt IS NULL THEN RAISE EXCEPTION 'Cần chọn kỳ.'; END IF; PERFORM private.k3_period_write_guard(typ,dt);
 IF btrim(coalesce(p->>'name',''))='' THEN RAISE EXCEPTION 'Tên mục tiêu không được trống.'; END IF;
 IF _id IS NULL THEN INSERT INTO public.k3_goals(user_id,period_type,period_start,period_end,name,description,expected_result,kpi_target,kpi_unit,due_date,department_id,request_key) VALUES(auth.uid(),typ,dt,public.k3_period_end(typ,dt),btrim(p->>'name'),nullif(btrim(p->>'description'),''),nullif(btrim(p->>'expected_result'),''),nullif(p->>'kpi_target','')::numeric,nullif(btrim(p->>'kpi_unit'),''),coalesce(nullif(p->>'due_date','')::date,public.k3_period_end(typ,dt)),public.biz_department_at(auth.uid(),greatest(dt,(SELECT period_effective_from FROM public.k3_settings WHERE id))),key) RETURNING * INTO g;
 ELSE UPDATE public.k3_goals SET name=btrim(p->>'name'),description=nullif(btrim(p->>'description'),''),expected_result=nullif(btrim(p->>'expected_result'),''),kpi_target=nullif(p->>'kpi_target','')::numeric,kpi_unit=nullif(btrim(p->>'kpi_unit'),''),due_date=nullif(p->>'due_date','')::date,revision=revision+1,updated_at=now() WHERE id=_id RETURNING * INTO g; END IF;
 INSERT INTO public.k3_plan_events(user_id,goal_id,actor_id,action,detail) VALUES(auth.uid(),g.id,auth.uid(),'goal_save',jsonb_build_object('before',to_jsonb(old),'after',to_jsonb(g))); RETURN to_jsonb(g); END$$;
CREATE FUNCTION public.k3_action_save(_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE a public.k3_actions; old public.k3_actions; g public.k3_goals; p jsonb:=_payload; _id uuid:=nullif(p->>'id','')::uuid; key uuid:=nullif(p->>'request_key','')::uuid; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập.'; END IF; PERFORM pg_advisory_xact_lock(hashtext('k3owner'),hashtext(auth.uid()::text));
 IF _id IS NOT NULL THEN SELECT * INTO old FROM public.k3_actions WHERE id=_id FOR UPDATE; IF old.id IS NULL OR old.user_id<>auth.uid() THEN RAISE EXCEPTION 'Bạn không được sửa hành động của người khác.'; END IF; IF (p->>'revision')::bigint IS DISTINCT FROM old.revision THEN RAISE EXCEPTION 'Hành động đã thay đổi. Vui lòng tải lại.'; END IF; ELSE IF key IS NULL THEN RAISE EXCEPTION 'Thiếu mã yêu cầu lưu hành động.'; END IF; SELECT * INTO a FROM public.k3_actions WHERE user_id=auth.uid() AND request_key=key; IF a.id IS NOT NULL THEN RETURN to_jsonb(a); END IF; END IF;
 SELECT * INTO g FROM public.k3_goals WHERE id=coalesce(old.goal_id,nullif(p->>'goal_id','')::uuid) FOR UPDATE; IF g.id IS NULL OR g.user_id<>auth.uid() THEN RAISE EXCEPTION 'Mục tiêu không thuộc bạn.'; END IF;
 PERFORM private.k3_period_write_guard(g.period_type,g.period_start);
 IF btrim(coalesce(p->>'name',''))='' THEN RAISE EXCEPTION 'Tên hành động không được trống.'; END IF;
 IF nullif(p->>'manual_progress','') IS NOT NULL AND btrim(coalesce(p->>'progress_source',''))='' THEN RAISE EXCEPTION 'Xác nhận tiến độ thủ công cần ghi nguồn.'; END IF;
 IF nullif(p->>'start_date','')::date> nullif(p->>'due_date','')::date THEN RAISE EXCEPTION 'Ngày bắt đầu phải trước hạn hoàn thành.'; END IF;
 IF _id IS NULL THEN INSERT INTO public.k3_actions(goal_id,user_id,name,kpi_target,kpi_unit,start_date,due_date,note,manual_progress,progress_source,request_key) VALUES(g.id,auth.uid(),btrim(p->>'name'),nullif(p->>'kpi_target','')::numeric,nullif(btrim(p->>'kpi_unit'),''),nullif(p->>'start_date','')::date,nullif(p->>'due_date','')::date,nullif(btrim(p->>'note'),''),nullif(p->>'manual_progress','')::smallint,nullif(btrim(p->>'progress_source'),''),key) RETURNING * INTO a;
 ELSE UPDATE public.k3_actions SET name=btrim(p->>'name'),kpi_target=nullif(p->>'kpi_target','')::numeric,kpi_unit=nullif(btrim(p->>'kpi_unit'),''),start_date=nullif(p->>'start_date','')::date,due_date=nullif(p->>'due_date','')::date,note=nullif(btrim(p->>'note'),''),manual_progress=nullif(p->>'manual_progress','')::smallint,progress_source=nullif(btrim(p->>'progress_source'),''),revision=revision+1,updated_at=now() WHERE id=_id RETURNING * INTO a; END IF;
 INSERT INTO public.k3_plan_events(user_id,goal_id,action_id,actor_id,action,detail) VALUES(auth.uid(),g.id,a.id,auth.uid(),'action_save',jsonb_build_object('before',to_jsonb(old),'after',to_jsonb(a))); RETURN to_jsonb(a); END$$;
CREATE OR REPLACE FUNCTION private.k3_task_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE d public.k3_days; a public.k3_actions; BEGIN
 SELECT * INTO d FROM public.k3_days WHERE id=NEW.day_id FOR UPDATE; IF d.id IS NULL OR d.user_id<>NEW.user_id OR d.work_date<>NEW.work_date THEN RAISE EXCEPTION 'Công việc không khớp ngày gốc hoặc chủ sở hữu.'; END IF;
 IF TG_OP='UPDATE' AND NEW.user_id<>OLD.user_id THEN RAISE EXCEPTION 'Không được đổi chủ sở hữu.'; END IF;
 IF TG_OP='UPDATE' AND (NEW.day_id<>OLD.day_id OR NEW.work_date<>OLD.work_date OR NEW.is_unscheduled<>OLD.is_unscheduled) AND coalesce(current_setting('k3.scheduling',true),'')<>'yes' THEN RAISE EXCEPTION 'Chỉ được đổi ngày qua thao tác xếp lịch riêng.'; END IF;
 IF NEW.action_id IS NOT NULL THEN SELECT * INTO a FROM public.k3_actions WHERE id=NEW.action_id; IF a.id IS NULL OR a.user_id<>NEW.user_id THEN RAISE EXCEPTION 'Hành động không thuộc chủ công việc.'; END IF; END IF;
 IF TG_OP='INSERT' THEN NEW.original_work_date:=CASE WHEN NEW.is_unscheduled THEN NULL ELSE NEW.work_date END; END IF;
 IF NEW.kpi_target<0 OR NEW.kpi_actual<0 THEN RAISE EXCEPTION 'KPI không được âm.'; END IF;
 IF TG_OP='INSERT' OR (NEW.kpi_target,NEW.kpi_actual,NEW.progress,NEW.status) IS DISTINCT FROM (OLD.kpi_target,OLD.kpi_actual,OLD.progress,OLD.status) THEN
 IF NEW.kpi_target>0 THEN NEW.progress:=least(100,round(coalesce(NEW.kpi_actual,0)/NEW.kpi_target*100)); END IF;
 IF NEW.status='done' AND ((NEW.kpi_target>0 AND coalesce(NEW.kpi_actual,0)<NEW.kpi_target) OR (coalesce(NEW.kpi_target,0)<=0 AND NEW.progress<100)) THEN RAISE EXCEPTION 'Chưa đạt chỉ tiêu hoàn thành. Hãy ghi nhận Kết thúc – Chưa đạt chỉ tiêu.'; END IF; END IF;
 IF NEW.status='incomplete' AND (TG_OP='INSERT' OR (NEW.status,NEW.problem,NEW.cause,NEW.solution) IS DISTINCT FROM (OLD.status,OLD.problem,OLD.cause,OLD.solution)) AND (btrim(coalesce(NEW.problem,''))='' OR btrim(coalesce(NEW.cause,''))='' OR btrim(coalesce(NEW.solution,''))='') THEN RAISE EXCEPTION 'Kết thúc chưa đạt cần đủ Vấn đề - Nguyên nhân - Giải pháp.'; END IF;
 IF TG_OP='UPDATE' THEN NEW.revision:=OLD.revision+1; END IF; RETURN NEW; END$$;
CREATE OR REPLACE FUNCTION private.k3_task_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN
 IF TG_OP='INSERT' OR (to_jsonb(NEW)-ARRAY['revision','updated_at','updated_by','note','links','how','place','sort_order']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['revision','updated_at','updated_by','note','links','how','place','sort_order']) THEN
 IF NOT NEW.is_unscheduled THEN UPDATE public.k3_days SET data_revision=data_revision+1 WHERE id=NEW.day_id; END IF;
 IF TG_OP='UPDATE' AND (OLD.day_id<>NEW.day_id OR NEW.is_unscheduled) AND NOT OLD.is_unscheduled THEN UPDATE public.k3_days SET data_revision=data_revision+1 WHERE id=OLD.day_id; END IF; END IF; RETURN NEW; END$$;
CREATE FUNCTION public.k3_plan_task_save(_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE p jsonb:=_payload; a public.k3_actions; g public.k3_goals; t public.k3_tasks; result jsonb; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập.'; END IF; PERFORM pg_advisory_xact_lock(hashtext('k3owner'),hashtext(auth.uid()::text));
 SELECT * INTO a FROM public.k3_actions WHERE id=nullif(p->>'action_id','')::uuid; SELECT * INTO g FROM public.k3_goals WHERE id=a.goal_id;
 IF a.id IS NULL OR a.user_id<>auth.uid() THEN RAISE EXCEPTION 'Hành động không thuộc bạn.'; END IF; PERFORM private.k3_period_write_guard(g.period_type,g.period_start);
 IF nullif(p->>'id','') IS NOT NULL THEN SELECT * INTO t FROM public.k3_tasks WHERE id=(p->>'id')::uuid; IF t.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Bạn không được sửa việc người khác.'; END IF;
 ELSE IF nullif(p->>'request_key','') IS NULL THEN RAISE EXCEPTION 'Thiếu mã yêu cầu công việc.'; END IF; SELECT * INTO t FROM public.k3_tasks WHERE user_id=auth.uid() AND request_key=(p->>'request_key')::uuid; IF t.id IS NOT NULL THEN RETURN to_jsonb(t); END IF; END IF;
 IF nullif(p->>'work_date','') IS NULL THEN p:=p||jsonb_build_object('work_date',coalesce(t.work_date,greatest(g.period_start,(SELECT effective_from FROM public.k3_settings WHERE id)))); END IF;
 result:=public.k3_task_save(p); PERFORM set_config('k3.scheduling','yes',true);
 UPDATE public.k3_tasks SET action_id=a.id,is_unscheduled=CASE WHEN t.id IS NULL THEN nullif(_payload->>'work_date','') IS NULL ELSE t.is_unscheduled END,original_work_date=CASE WHEN t.id IS NULL AND nullif(_payload->>'work_date','') IS NULL THEN NULL ELSE original_work_date END WHERE id=(result->>'id')::uuid RETURNING * INTO t;
 PERFORM set_config('k3.scheduling','',true);
 INSERT INTO public.k3_task_events(day_id,task_id,actor_id,action,detail) VALUES(t.day_id,t.id,auth.uid(),'link',jsonb_build_object('action_id',a.id,'is_unscheduled',t.is_unscheduled)); RETURN to_jsonb(t); END$$;
CREATE FUNCTION public.k3_task_schedule(_id uuid,_date date,_revision bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE t public.k3_tasks; old public.k3_tasks; d public.k3_days; s public.k3_settings; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập.'; END IF; PERFORM pg_advisory_xact_lock(hashtext('k3owner'),hashtext(auth.uid()::text)); SELECT * INTO old FROM public.k3_tasks WHERE id=_id FOR UPDATE;
 IF old.id IS NULL OR old.user_id<>auth.uid() OR old.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Bạn không được xếp lịch việc người khác.'; END IF; IF old.revision<>_revision OR _revision IS NULL THEN RAISE EXCEPTION 'Công việc đã thay đổi. Vui lòng tải lại.'; END IF;
 PERFORM private.k3_write_guard(_date); IF _date<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AND old.work_date<>_date THEN RAISE EXCEPTION 'Chỉ được xếp lịch sang hôm nay hoặc ngày tương lai.'; END IF;
 SELECT * INTO s FROM public.k3_settings WHERE id;
 INSERT INTO public.k3_days(user_id,work_date,planned_at) VALUES(auth.uid(),_date,now()) ON CONFLICT(user_id,work_date) DO NOTHING;
 SELECT * INTO d FROM public.k3_days WHERE user_id=auth.uid() AND work_date=_date FOR UPDATE;
 IF old.is_focus AND (SELECT count(*) FROM public.k3_tasks WHERE day_id=d.id AND is_focus AND deleted_at IS NULL AND NOT is_unscheduled AND id<>old.id)>=s.max_focus THEN RAISE EXCEPTION 'Ngày mới đã đủ mũi khoan trọng tâm.'; END IF;
 PERFORM set_config('k3.scheduling','yes',true);
 UPDATE public.k3_tasks SET day_id=d.id,work_date=_date,is_unscheduled=false,original_work_date=coalesce(original_work_date,work_date,_date),updated_at=now(),updated_by=auth.uid() WHERE id=old.id RETURNING * INTO t;
 PERFORM set_config('k3.scheduling','',true);
 INSERT INTO public.k3_task_events(day_id,task_id,actor_id,action,detail) VALUES(old.day_id,t.id,auth.uid(),'schedule',jsonb_build_object('before',to_jsonb(old),'after',to_jsonb(t)));
 IF old.day_id<>t.day_id THEN INSERT INTO public.k3_task_events(day_id,task_id,actor_id,action,detail) VALUES(t.day_id,t.id,auth.uid(),'schedule',jsonb_build_object('before',to_jsonb(old),'after',to_jsonb(t))); END IF; RETURN to_jsonb(t); END$$;
REVOKE ALL ON FUNCTION public.k3_goal_save(jsonb),public.k3_action_save(jsonb),public.k3_plan_task_save(jsonb),public.k3_task_schedule(uuid,date,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.k3_goal_save(jsonb),public.k3_action_save(jsonb),public.k3_plan_task_save(jsonb),public.k3_task_schedule(uuid,date,bigint) TO authenticated;